head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.onpageload = function() {
	ipt_index.setValue("2");
	// 41행: col2·extRow1 외 같은 값. extRow1 있는 Row 만 2번째 줄(extRow) 표시
	var jsonData = [];
	for (var n = 0; n < 41; n++) {
		jsonData.push({
			"col2": "Amoxicillin 500mg" + (n < 9 ? "" + (n + 1) + (n + 1) : ""),
			"chk": "",
			"col3": "내복약-원내",
			"col4": "1",
			"col5": "c",
			"col6": "1",
			"col7": "1",
			"col8": "",
			"col9": "급여",
			"col10": "A",
			"col11": "IM",
			"col12": "",
			"col13": "**",
			"col14": "",
			"col15": "icu",
			"col16": "",
			"col17": "20190823",
			"col18": "O",
			"col19": "im31",
			"col20": "1",
			"col21": "미처리",
			"extRow2": "",
			"extRow1": n == 0 ? "123123" : (n % 5 == 4 ? "aabb" : (n % 5 == 0 ? "321312" : ""))
		});
	}
	dtl_data.setJSON(jsonData);
	var chkColumnStr = "extChkRow,extRow1,extRow2";
	scwin.chkMultiCellVisible(grd_sample1, "extRow1", chkColumnStr);
};
scwin.chkMultiCellVisible = function(grdObj, chkColumn, columnArrStr, modifiedIndex) {
	var grdComp;
	if (typeof grdObj !== "undefined") {
		if (typeof grdObj === "string") {
			grdComp = $p.getComponentById(grdObj);
		} else {
			grdComp = grdObj;
		}
	}
	var dcObjId = grdComp.getDataList();
	var dcObj = $p.getComponentById(dcObjId);
	var rowCnt = dcObj.getTotalRow();
	var multiColumnArr = columnArrStr.split(",");
	var multiColumnArrLength = multiColumnArr.length;
	for (var i = 0; i < rowCnt; i++) {
		for (var j = 0; j < multiColumnArrLength; j++) {
			var cellName = multiColumnArr[j];
			var txt = dcObj.getCellData(i, chkColumn);
			if (txt.trim() != "") {
				grdComp.setCellVisible(i, cellName, true);
			} else {
				if (modifiedIndex == i) {
					continue;
				}
				grdComp.setCellVisible(i, cellName, false);
			}
		}
	}
};
scwin.insertMultiRow = function(grdObj, rowIndex, cellData, chkColumn, columnArrStr) {
	var grdComp;
	if (typeof grdObj !== "undefined") {
		if (typeof grdObj === "string") {
			grdComp = $p.getComponentById(grdObj);
		} else {
			grdComp = grdObj;
		}
	}
	scwin.clearMultiRow(grdComp, columnArrStr);
	var dcObjId = grdComp.getDataList();
	var dcObj = $p.getComponentById(dcObjId);
	var insertedIndex = dcObj.insertRow(rowIndex);
	dcObj.setCellData(insertedIndex, chkColumn, cellData);
	scwin.chkMultiCellVisible(grdObj, chkColumn, columnArrStr, insertedIndex);
};
scwin.removeMultiRow = function(grdObj, rowIndex, chkColumn, columnArrStr) {
	var grdComp;
	if (typeof grdObj !== "undefined") {
		if (typeof grdObj === "string") {
			grdComp = $p.getComponentById(grdObj);
		} else {
			grdComp = grdObj;
		}
	}
	scwin.clearMultiRow(grdComp, columnArrStr);
	var dcObjId = grdComp.getDataList();
	var dcObj = $p.getComponentById(dcObjId);
	var removedIndex = dcObj.removeRow(rowIndex);
	scwin.chkMultiCellVisible(grdObj, chkColumn, columnArrStr);
};
scwin.clearMultiRow = function(grdObj, columnArrStr) {
	var grdComp;
	if (typeof grdObj !== "undefined") {
		if (typeof grdObj === "string") {
			grdComp = $p.getComponentById(grdObj);
		} else {
			grdComp = grdObj;
		}
	}
	var dcObjId = grdComp.getDataList();
	var dcObj = $p.getComponentById(dcObjId);
	var rowCnt = dcObj.getTotalRow();
	var multiColumnArr = columnArrStr.split(",");
	var multiColumnArrLength = multiColumnArr.length;
	for (var i = 0; i < rowCnt; i++) {
		for (var j = 0; j < multiColumnArrLength; j++) {
			var cellName = multiColumnArr[j];
			grdComp.setCellVisible(i, cellName, true);
		}
	}
};
scwin.trigger1_onclick = function(e) {
	var idx = ipt_index.getValue();
	var chkColumnStr = "extChkRow,extRow1,extRow2";
	scwin.insertMultiRow(grd_sample1, idx, "테스트 값1", "extRow1", chkColumnStr);
};
scwin.trigger2_onclick = function(e) {
	var idx = ipt_index.getValue();
	var chkColumnStr = "extChkRow,extRow1,extRow2";
	scwin.removeMultiRow(grd_sample1, idx, "extRow1", chkColumnStr);
};
scwin.checkVal = function() {
	return scwin.__getDom($p.id + 'grd_sample1_cell_2_22').children[0].innerText == "테스트 값1";
}
